package com.waypoint.order;
import com.waypoint.order.dto.OrderModels.*;import com.waypoint.order.exception.ApiException;import com.waypoint.order.repository.OrderRepository;import com.waypoint.order.service.OrderService;import org.junit.jupiter.api.*;import java.math.BigDecimal;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class OrderServiceTest {OrderRepository repo;UUID manager=UUID.randomUUID();PlaceOrderRequest request;
 @BeforeEach void setup(){repo=mock(OrderRepository.class);when(repo.outletFor(manager)).thenReturn("OUT-1");when(repo.place(anyString(),any(),any(),any())).thenReturn(UUID.randomUUID());request=new PlaceOrderRequest(List.of(new ItemRequest("SKU",2,BigDecimal.ONE,BigDecimal.ONE,"AMBIENT",BigDecimal.TEN)),LocalDate.of(2026,10,4),null);}
 @Test void cutoffClockIsInjectableAndRejectsNextDay(){var clock=Clock.fixed(Instant.parse("2026-10-03T11:00:01Z"),ZoneId.of("Asia/Colombo"));var service=new OrderService(repo,clock,"16:00");assertThatThrownBy(()->service.place(manager,"STORE_MANAGER",request)).isInstanceOfSatisfying(ApiException.class,e->{assertThat(e.code).isEqualTo("CUTOFF_PASSED");assertThat(e.extra.get("nextEligibleDate")).isEqualTo(LocalDate.of(2026,10,5));});}
 @Test void freshOutletCanPlaceAmbientAndChilledOrdersSameDay(){var service=new OrderService(repo,Clock.fixed(Instant.parse("2026-10-03T08:00:00Z"),ZoneId.of("Asia/Colombo")),"16:00");service.place(manager,"STORE_MANAGER",request);var chilled=new PlaceOrderRequest(List.of(new ItemRequest("COLD",1,BigDecimal.ONE,BigDecimal.ONE,"CHILLED",BigDecimal.TEN)),request.requestedDeliveryDate(),null);service.place(manager,"STORE_MANAGER",chilled);verify(repo,times(2)).place(eq("OUT-1"),eq(manager),any(),any());}
 @Test void managerCannotReadAnotherOutletOrder(){UUID order=UUID.randomUUID();doThrow(new ApiException(org.springframework.http.HttpStatus.NOT_FOUND,"ORDER_NOT_FOUND","Order not found")).when(repo).ensureOwned(order,"OUT-1");var service=new OrderService(repo,Clock.systemUTC(),"16:00");assertThatThrownBy(()->service.get(order,manager,"STORE_MANAGER")).isInstanceOf(ApiException.class);}
}
